// Patching to support node.js extensions.

import { Annotated } from './annotated.js';
import { Bytes } from './bytes.js';
import { Set, EncodableDictionary } from './dictionary.js';
import { stringify } from './text.js';

import * as util from 'util';

[Bytes, Annotated, Set, EncodableDictionary].forEach((C) => {
    (C as any).prototype[util.inspect.custom] =
        function (_depth: any, _options: any) {
            return stringify(this, { indent: 2 });
        };
});
